ng></div><div><span>Embarcación</span><strong>{{ $reservation->departure->vessel->name }}</strong></div><div><span>Total</span><strong>S/ {{ number_format((float)$reservation->total_amount,2) }}</strong></div></div><p><strong>Asientos:</strong><br>@foreach($reservation->seats as $seat)<span class="seat">{{ $seat->seat->code }} · {{ $seat->passenger_name }}</span>@endforeach</p>@endif</section></main></body></html>

